from itertools import product, combinations
from collections import Counter


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    start_mask = bit.get(source, 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    state = (source, start_mask, 0)
    best = {state: start}
    queue = [(start, source, start_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != time:
            continue
        if (node == data["target"] and mask == full and
                (coupon_rule != "exact" or used == data["coupons"])):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


def _build_route(coupon_rule, minimum_duration):
    return lambda data: _route(data, coupon_rule, minimum_duration)


def _build_component_06():
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            tax = rounded(net * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows_by_name = {}
        for name in names:
            rows_by_name[name] = {
                row["version"]: row for row in packages[name]
            }

        choices = []
        for name in names:
            choices.append([-1] + sorted(rows_by_name[name]))

        best_vector = None
        best_result = None
        roots = data["roots"]
        for vector in product(*choices):
            versions = dict(zip(names, vector))
            if any(versions[name] < bounds[0] or versions[name] > bounds[1]
                   for name, bounds in roots.items()
                   if versions[name] != -1):
                continue
            if any(versions[name] == -1 or not bounds[0] <= versions[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue
            if any(version != -1 and
                   (version in blocked.get(name, []) or
                    (name in pins and version != pins[name]))
                   for name, version in versions.items()):
                continue

            edges = {}
            valid = True
            for name, version in versions.items():
                if version == -1:
                    continue
                deps = []
                row = rows_by_name[name][version]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    selected = versions[target]
                    if selected == -1 or not dep["min"] <= selected <= dep["max"]:
                        valid = False
                        break
                    deps.append(target)
                edges[name] = deps
                if not valid:
                    break
            if not valid:
                continue

            # The installation must be precisely the closure of the roots.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                if versions[name] == -1:
                    valid = False
                    break
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if not valid or any((versions[name] != -1) != (name in reachable)
                                for name in names):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(dep) for dep in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(visit(name) for name in reachable):
                continue

            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_result = {name: version for name, version in versions.items()
                               if version != -1}

        return ({"versions": best_result} if best_result is not None
                else {"error": "unsatisfiable"})
    return solve


def _build_component_08():
    def solve(data):
        k = data["k"]
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        if len(jobs) < k:
            return {"error": "impossible"}
        for chosen in combinations(jobs, k):
            ids = {job["id"] for job in chosen}
            if not mandatory.issubset(ids):
                continue
            counts = Counter(job["group"] for job in chosen)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active = []
            valid = True
            for job in sorted(chosen, key=lambda row: (row["start"], row["end"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > 2:
                    valid = False
                    break
            if not valid:
                continue

            value = sum(job["value"] for job in chosen)
            selected = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and selected > best_ids)):
                best_value, best_ids = value, selected

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


